// TestProposeWorkflowLabelMatchesTheGate checks that the propose
// workflow creates minion-reviewed with the colour and description the
// gate gives it. The workflow uses --force, so a difference would make
// each run overwrite the label the other one set.
func TestProposeWorkflowLabelMatchesTheGate(t *testing.T) {
	raw, err := os.ReadFile("../../.github/workflows/propose.yml")
	if err != nil {
		t.Fatalf("read propose workflow: %v", err)
	}
	var create string
	for _, line := range strings.Split(string(raw), "\n") {
		if strings.Contains(line, "gh label create "+ReviewedLabel) {
			create = line
			break
		}
	}
	if create == "" {
		t.Fatal("the propose workflow never creates " + ReviewedLabel)
	}
	for _, want := range []string{
		"--color " + reviewedLabelColor,
		`--description "` + reviewedLabelDescription + `"`,
	} {
		if !strings.Contains(create, want) {
			t.Errorf("the propose workflow label step lacks %q:\n%s", want, create)
		}
	}
}
